; ===========================================================================
;  MTKPLAY - standalone replayer for MSXTRACK songs (.MTK), for games
;  and demos. GENERATED by tools/gen_replayer.py from the tracker's own
;  engine (src/player_core.asm) - edit those, not this file.
;
;  Usage:
;      MTK_RAM equ 0E000h          ; MTK_RAMSIZE (175) bytes of RAM
;              include "mtkplay.asm"
;
;      ld hl,song : call mtk_init  ; Z = ok
;      xor a      : call mtk_start ; play from position 0
;      ...and call mtk_frame once per frame from your interrupt hook
;      (H.TIMI), e.g.  hook: call mtk_frame : ret
;
;      ld a,10 : ld b,49 : ld c,2 : call mtk_sfx   ; instrument 10 as a
;                                   ; sound effect at C-5 on channel C
;  Calls
;      mtk_init      HL = .MTK file              -> Z ok / NZ bad file
;      mtk_start     A = order position          music on (loops)
;      mtk_stop                                  music off
;      mtk_frame     once per frame (interrupt)  plays and writes the PSG
;      mtk_sfx       A = instrument, B = note, C = channel
;      mtk_sfx_stop                              end the sound effect
;      mtk_sfx_bank  HL = .MTK file               effects from another file
;  Readable state
;      mtk_PL_PLAYING (0 = stopped), mtk_PL_ORDPOS, mtk_PL_ROW, mtk_SFX_ON
;
;  Notes
;  - The song data is only read, so it can stay in ROM.
;  - mtk_init/start/stop/sfx briefly disable interrupts and return with
;    them enabled. mtk_frame and the hook may use all registers; the MSX
;    BIOS saves them before calling H.TIMI.
;  - Port A0h/A1h only; register 7 keeps the MSX I/O bits (10xxxxxx).
;  - Labels all start with mtk_ / MTK_. Plain Z80 syntax (built and tested
;    with pasmo). About 2.3KB of code and tables.
; ===========================================================================

; ---------------------------------------------------------------------------
; RAM used by the replayer (MTK_RAM must be defined before including)
; ---------------------------------------------------------------------------
mtk_CHAN0       equ MTK_RAM
mtk_CHAN1       equ MTK_RAM+32
mtk_CHAN2       equ MTK_RAM+64
mtk_SFXCH       equ MTK_RAM+96
mtk_PSGREG      equ MTK_RAM+128         ; 14 bytes
mtk_PL_PLAYING  equ MTK_RAM+142
mtk_PL_TICK     equ MTK_RAM+143
mtk_PL_SPEED    equ MTK_RAM+144
mtk_PL_ORDPOS   equ MTK_RAM+145
mtk_PL_ROW      equ MTK_RAM+146
mtk_PL_PATPTR   equ MTK_RAM+147         ; 2 bytes
mtk_PL_JUMP     equ MTK_RAM+149
mtk_PL_BREAK    equ MTK_RAM+150
mtk_PL_FIRST    equ MTK_RAM+151
mtk_PL_ENVTRIG  equ MTK_RAM+152
mtk_PL_ENVMAN   equ MTK_RAM+153
mtk_PL_ROWFLAG  equ MTK_RAM+154
mtk_PL_DISPROW  equ MTK_RAM+155
mtk_PL_DISPORD  equ MTK_RAM+156
mtk_PU_BIT      equ MTK_RAM+157
mtk_SNG_SPEED   equ MTK_RAM+158         ; these four stay in file order
mtk_SNG_PATLEN  equ MTK_RAM+159
mtk_SNG_LEN     equ MTK_RAM+160
mtk_SNG_LOOP    equ MTK_RAM+161
mtk_PL_ORDERS   equ MTK_RAM+162         ; 2 bytes
mtk_PL_INSTR    equ MTK_RAM+164         ; 2 bytes
mtk_PATBASE     equ MTK_RAM+166         ; 2 bytes
mtk_NUMPAT      equ MTK_RAM+168
mtk_SFX_ON      equ MTK_RAM+169
mtk_SFX_CHAN    equ MTK_RAM+170
mtk_SFX_TIME    equ MTK_RAM+171         ; 2 bytes, 0 = until stopped
mtk_SFX_INSTR   equ MTK_RAM+173         ; 2 bytes
MTK_RAMSIZE     equ 175

mtk_NOTE_OFF    equ 97
mtk_PSG_ADR     equ 0A0h
mtk_PSG_WR      equ 0A1h

; ---------------------------------------------------------------------------
; Public API
; ---------------------------------------------------------------------------

; mtk_init - prepare a song. HL = start of the .MTK file in memory (ROM or
; RAM). Returns Z if it is a valid song, NZ if not. Music is stopped.
; Sound effects use this song's instruments until mtk_sfx_bank is called.
mtk_init:
        push hl
        ld de,mtk_magic
        ld b,6
mtk_in_cmp:
        ld a,(de)
        cp (hl)
        jr nz,mtk_in_bad
        inc hl
        inc de
        djnz mtk_in_cmp
        ld a,(hl)               ; format version
        cp 1
        jr nz,mtk_in_bad
        inc hl
        ld a,(hl)               ; pattern count
        or a
        jr z,mtk_in_bad
        cp 65
        jr nc,mtk_in_bad
        di
        push hl                 ; clear all replayer RAM
        ld hl,MTK_RAM
        ld b,MTK_RAMSIZE
mtk_in_clr:
        ld (hl),0
        inc hl
        djnz mtk_in_clr
        pop hl
        ld (mtk_NUMPAT),a
        inc hl
        ld de,mtk_SNG_SPEED     ; speed, rows, length, restart
        ld bc,4
        ldir
        pop hl
        ld de,8+32
        add hl,de
        ld (mtk_PL_ORDERS),hl
        ld de,128
        add hl,de
        ld (mtk_PL_INSTR),hl
        ld (mtk_SFX_INSTR),hl
        ld de,16*96
        add hl,de
        ld (mtk_PATBASE),hl
        call mtk_reset_chans
        ei
        xor a
        ret
mtk_in_bad:
        pop hl
        or 1
        ret

mtk_magic:
        db "MSXTRK"

; mtk_start - play the song from order position A (0 = beginning).
; It loops to the song's restart position at the end.
mtk_start:
        ld hl,mtk_SNG_LEN
        cp (hl)
        jr c,mtk_st_ok
        xor a
mtk_st_ok:
        ld b,a
        ld c,0
        ld a,1
        jp mtk_play_start

; mtk_stop - stop the music (sound effects keep playing).
mtk_stop:
        jp mtk_play_stop

; mtk_frame - call once per video frame, from the interrupt (H.TIMI).
; Advances music and sound effects and writes the PSG.
mtk_frame:
        call mtk_player_tick
        ld a,(mtk_SFX_ON)
        or a
        jp z,mtk_psg_update
        ld ix,mtk_SFXCH
        call mtk_chan_tick
        ld a,(mtk_SFX_CHAN)     ; the effect replaces the music on its channel
        ld l,a
        ld h,0
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        ld de,mtk_CHAN0+mtk_C_OPL
        add hl,de
        ex de,hl
        ld hl,mtk_SFXCH+mtk_C_OPL
        ld bc,5                 ; period, volume, mixer, noise
        ldir
        ld hl,(mtk_SFX_TIME)
        ld a,h
        or l
        jp z,mtk_psg_update
        dec hl
        ld (mtk_SFX_TIME),hl
        ld a,h
        or l
        jp nz,mtk_psg_update
        ld (mtk_SFX_ON),a
        jp mtk_psg_update

; mtk_sfx - play instrument A (1-15) as a sound effect at note B (1-96,
; 49 = C-5) on channel C (0-2), over the music on that channel. A new
; effect replaces the previous one. A non-looping instrument ends after its
; last step; a looping one plays until mtk_sfx_stop.
mtk_sfx:
        di
        push bc
        ld l,a                  ; HL = instrument
        ld h,0
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        ld e,l
        ld d,h
        add hl,hl
        add hl,de
        ld de,(mtk_SFX_INSTR)
        add hl,de
        push hl
        ld hl,mtk_SFXCH         ; fresh channel state
        ld b,32
mtk_sx_clr:
        ld (hl),0
        inc hl
        djnz mtk_sx_clr
        ld ix,mtk_SFXCH
        ld (ix+mtk_C_VOL),15
        ld (ix+mtk_C_FX),0FFh
        ld (ix+mtk_C_CUT),0FFh
        ld (ix+mtk_C_NOVR),0FFh
        pop hl
        ld (ix+mtk_C_INSL),l
        ld (ix+mtk_C_INSH),h
        ld e,(hl)               ; length in frames = steps * speed
        inc hl
        ld a,(hl)               ; loop step
        inc hl
        cp e
        ld bc,0
        jr c,mtk_sx_time        ; loops: no end
        ld a,(hl)
        or a
        jr nz,mtk_sx_spd
        inc a
mtk_sx_spd:
        ld b,a
        xor a
        ld d,a
mtk_sx_mul:
        add a,e
        jr nc,mtk_sx_nc
        inc d
mtk_sx_nc:
        djnz mtk_sx_mul
        ld c,a
        ld b,d
mtk_sx_time:
        ld (mtk_SFX_TIME),bc
        pop bc
        ld a,c
        ld (mtk_SFX_CHAN),a
        ld d,b
        call mtk_trigger_note
        ld a,1
        ld (mtk_SFX_ON),a
        ei
        ret

; mtk_sfx_stop - end the current sound effect.
mtk_sfx_stop:
        xor a
        ld (mtk_SFX_ON),a
        ret

; mtk_sfx_bank - take sound effect instruments from another .MTK file
; (HL = start of that file), e.g. a song that only holds effects.
mtk_sfx_bank:
        ld de,8+32+128
        add hl,de
        ld (mtk_SFX_INSTR),hl
        ret

; ---------------------------------------------------------------------------
; Internals
; ---------------------------------------------------------------------------

; A = pattern -> HL = address (preserves BC)
mtk_get_pat_addr:
        ld hl,mtk_NUMPAT
        cp (hl)
        jr c,mtk_gp_ok
        xor a
mtk_gp_ok:
        ld e,a                  ; DE = A * 768
        add a,a
        add a,e
        ld d,a
        ld e,0
        ld hl,(mtk_PATBASE)
        add hl,de
        ret

; ===========================================================================
; MSXTRACK replay engine core
; Shared by the tracker (player.asm) and the standalone game replayer
; (replayer/mtkplay.asm is generated from this file by tools/gen_replayer.py).
; Needs from the includer: get_pat_addr, the RAM variables, PL_ORDERS and
; PL_INSTR (pointers to the order list and instruments), the SNG_* settings
; and the tables notetab, voltab and sinetab.
; ===========================================================================

; ---- channel structure (IX relative) ----
mtk_C_NOTE      equ 0           ; base note 1..96
mtk_C_INS       equ 1           ; instrument number
mtk_C_INSL      equ 2           ; instrument pointer
mtk_C_INSH      equ 3
mtk_C_STEP      equ 4           ; instrument sequence step
mtk_C_STICK     equ 5           ; tick counter within step
mtk_C_ACTIVE    equ 6
mtk_C_VOL       equ 7           ; channel volume 0..15
mtk_C_SWPL      equ 8           ; instrument pitch sweep accumulator
mtk_C_SWPH      equ 9
mtk_C_SLDL      equ 10          ; effect pitch slide accumulator
mtk_C_SLDH      equ 11
mtk_C_FX        equ 12          ; running effect (FF none)
mtk_C_FXP       equ 13
mtk_C_ARPC      equ 14
mtk_C_VIBP      equ 15
mtk_C_CUT       equ 16
mtk_C_DLY       equ 17
mtk_C_DNOTE     equ 18
mtk_C_DIV       equ 19
mtk_C_DFL       equ 20
mtk_C_DET       equ 21
mtk_C_NOVR      equ 22
mtk_C_MUTE      equ 23
mtk_C_OPL       equ 24          ; output: tone period
mtk_C_OPH       equ 25
mtk_C_OVOL      equ 26          ; output: volume (16 = hardware envelope)
mtk_C_OMIX      equ 27          ; output: bit0 tone, bit1 noise
mtk_C_ONOI      equ 28          ; output: noise period
mtk_C_OENV      equ 29
mtk_C_PSPD      equ 30          ; tone portamento speed
mtk_C_VIBPAR    equ 31          ; vibrato speed/depth
mtk_CHSIZE      equ 32

; ---- instrument structure ----
mtk_I_LEN       equ 0
mtk_I_LOOP      equ 1           ; FF = no loop (hold last step)
mtk_I_SPEED     equ 2
mtk_I_SHAPE     equ 3
mtk_I_EMODE     equ 4           ; 0 fixed period, 1-4 follow note
mtk_I_EPERL     equ 5
mtk_I_EPERH     equ 6
mtk_I_NAME      equ 8
mtk_I_STEPS     equ 16
mtk_STEPSZ      equ 5           ; vol, arp, sweep, noise, flags(T=1 N=2 E=4)

; One frame of the sequencer and instruments (no PSG output yet)
mtk_player_tick:
        ld a,(mtk_PL_PLAYING)
        or a
        jr z,mtk_pf_chans
        ld hl,mtk_PL_TICK
        dec (hl)
        jr nz,mtk_pf_chans
        call mtk_process_row
        ld a,(mtk_PL_SPEED)
        ld (mtk_PL_TICK),a
        ld a,1
        ld (mtk_PL_FIRST),a
mtk_pf_chans:
        ld ix,mtk_CHAN0
        call mtk_chan_tick
        ld ix,mtk_CHAN1
        call mtk_chan_tick
        ld ix,mtk_CHAN2
        call mtk_chan_tick
        xor a
        ld (mtk_PL_FIRST),a
        ret

; ---------------------------------------------------------------------------
; Read one row of the current pattern and move the song position on
; ---------------------------------------------------------------------------
mtk_process_row:
        ld a,(mtk_PL_ROW)
        ld (mtk_PL_DISPROW),a
        ld a,(mtk_PL_ORDPOS)
        ld (mtk_PL_DISPORD),a
        ld a,0FFh
        ld (mtk_PL_JUMP),a
        ld (mtk_PL_BREAK),a
        ld a,(mtk_PL_ROW)
        call mtk_row_offset
        ld de,(mtk_PL_PATPTR)
        add hl,de
        ld ix,mtk_CHAN0
        call mtk_process_cell
        ld ix,mtk_CHAN1
        call mtk_process_cell
        ld ix,mtk_CHAN2
        call mtk_process_cell
        ld a,1
        ld (mtk_PL_ROWFLAG),a
        ld a,(mtk_PL_JUMP)
        cp 0FFh
        jr nz,mtk_pr_jump
        ld a,(mtk_PL_BREAK)
        cp 0FFh
        jr nz,mtk_pr_break
        ld a,(mtk_PL_ROW)
        inc a
        ld hl,mtk_SNG_PATLEN
        cp (hl)
        jr nc,mtk_pr_endpat
        ld (mtk_PL_ROW),a
        ret
mtk_pr_endpat:
        xor a
mtk_pr_break:
        ld b,a
        ld a,(mtk_PL_PLAYING)
        cp 2
        jr z,mtk_pr_setrow
        ld a,(mtk_PL_ORDPOS)
        inc a
        jr mtk_pr_setord
mtk_pr_jump:
        ld c,a
        ld a,(mtk_PL_BREAK)
        cp 0FFh
        jr nz,mtk_pr_j1
        xor a
mtk_pr_j1:  ld b,a
        ld a,(mtk_PL_PLAYING)
        cp 2
        jr z,mtk_pr_setrow
        ld a,c
mtk_pr_setord:                      ; A = order position, B = row
        ld hl,mtk_SNG_LEN
        cp (hl)
        jr c,mtk_pr_ordok
        ld a,(mtk_SNG_LOOP)
        cp (hl)
        jr c,mtk_pr_ordok
        xor a
mtk_pr_ordok:
        ld (mtk_PL_ORDPOS),a
        call mtk_set_patptr
mtk_pr_setrow:
        ld a,b
        ld hl,mtk_SNG_PATLEN
        cp (hl)
        jr c,mtk_pr_rowok
        xor a
mtk_pr_rowok:
        ld (mtk_PL_ROW),a
        ret

; A = order position -> PL_PATPTR (preserves BC)
mtk_set_patptr:
        ld e,a
        ld d,0
        ld hl,(mtk_PL_ORDERS)
        add hl,de
        ld a,(hl)
        call mtk_get_pat_addr
        ld (mtk_PL_PATPTR),hl
        ret

; A = row -> HL = A*12
mtk_row_offset:
        ld l,a
        ld h,0
        add hl,hl
        add hl,hl
        ld e,l
        ld d,h
        add hl,hl
        add hl,de
        ret

; HL = cell, IX = channel. Returns HL += 4
mtk_process_cell:
        ld d,(hl)
        inc hl
        ld e,(hl)
        inc hl
        ld b,(hl)
        inc hl
        ld c,(hl)
        inc hl
        push hl
        ld (ix+mtk_C_CUT),0FFh
        ld (ix+mtk_C_DLY),0
        bit 6,b
        jr z,mtk_pc_now
        ld a,b
        and 0Fh
        cp 9
        jr nz,mtk_pc_now
        ld a,c
        or a
        jr z,mtk_pc_now
        inc a                   ; counted down from this same frame on
        jr nz,mtk_pc_dly
        dec a
mtk_pc_dly: ld (ix+mtk_C_DLY),a         ; 9xx: note delay
        ld (ix+mtk_C_DNOTE),d
        ld (ix+mtk_C_DIV),e
        ld (ix+mtk_C_DFL),b
        pop hl
        ret
mtk_pc_now: call mtk_apply_cell
        pop hl
        ret

; D = note, E = instrument/volume, B = flags, C = fx parameter, IX = channel
mtk_apply_cell:
        ld a,e
        and 0F0h
        jr z,mtk_ac_noins
        rrca
        rrca
        rrca
        rrca
        call mtk_set_instr
mtk_ac_noins:
        bit 7,b
        jr z,mtk_ac_novol
        ld a,e
        and 0Fh
        ld (ix+mtk_C_VOL),a
mtk_ac_novol:
        ld a,d                  ; a new note ends the running effect
        or a
        jr z,mtk_ac_fx
        cp mtk_NOTE_OFF
        jr z,mtk_ac_fx
        ld (ix+mtk_C_FX),0FFh
mtk_ac_fx:  bit 6,b
        call nz,mtk_apply_fx
        ld a,d
        or a
        ret z
        cp mtk_NOTE_OFF
        jr nz,mtk_ac_note
        ld (ix+mtk_C_ACTIVE),0
        ret
mtk_ac_note:
        ld a,(ix+mtk_C_FX)
        cp 3
        jr nz,mtk_trigger_note
        ld a,(ix+mtk_C_ACTIVE)
        or a
        jr z,mtk_trigger_note
        push de                 ; tone portamento: keep pitch, slide to 0
        ld a,(ix+mtk_C_NOTE)
        call mtk_note_period
        ld e,(ix+mtk_C_SLDL)
        ld d,(ix+mtk_C_SLDH)
        add hl,de
        pop de
        ld (ix+mtk_C_NOTE),d
        push hl
        ld a,d
        call mtk_note_period
        ex de,hl
        pop hl
        or a
        sbc hl,de
        ld (ix+mtk_C_SLDL),l
        ld (ix+mtk_C_SLDH),h
        ret

mtk_trigger_note:                   ; D = note
        ld (ix+mtk_C_NOTE),d
        ld (ix+mtk_C_ACTIVE),1
        xor a
        ld (ix+mtk_C_STEP),a
        ld (ix+mtk_C_STICK),a
        ld (ix+mtk_C_SWPL),a
        ld (ix+mtk_C_SWPH),a
        ld (ix+mtk_C_SLDL),a
        ld (ix+mtk_C_SLDH),a
        ld (ix+mtk_C_VIBP),a
        ld (ix+mtk_C_ARPC),a
        ld l,(ix+mtk_C_INSL)
        ld h,(ix+mtk_C_INSH)
        push hl
        ld de,mtk_I_STEPS+4
        add hl,de
        pop de
        bit 2,(hl)              ; step 0 uses the hardware envelope?
        ret z
        ld hl,mtk_I_SHAPE
        add hl,de
        ld a,(hl)
        and 0Fh
        ld (mtk_PSGREG+13),a
        ld a,1
        ld (mtk_PL_ENVTRIG),a
        ret

; A = note -> HL = tone period (destroys DE)
mtk_note_period:
        ld l,a
        ld h,0
        add hl,hl
        ld de,mtk_notetab
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        ex de,hl
        ret

; A = instrument 1..15 (preserves BC, DE)
mtk_set_instr:
        push de
        ld (ix+mtk_C_INS),a
        call mtk_ins_addr
        ld (ix+mtk_C_INSL),l
        ld (ix+mtk_C_INSH),h
        pop de
        ret

; A = instrument -> HL = address (destroys DE)
mtk_ins_addr:
        ld l,a
        ld h,0
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        add hl,hl
        ld e,l
        ld d,h
        add hl,hl
        add hl,de
        ld de,(mtk_PL_INSTR)
        add hl,de
        ret

; ---- effects applied when a row is read (B = flags, C = param) ----
mtk_apply_fx:
        ld a,b
        and 0Fh
        add a,a
        ld l,a
        ld h,0
        push de
        ld de,mtk_fx_table
        add hl,de
        pop de
        ld a,(hl)
        inc hl
        ld h,(hl)
        ld l,a
        jp (hl)

mtk_fx_table:
        dw mtk_fx_arp,mtk_fx_cont,mtk_fx_cont,mtk_fx_porta,mtk_fx_vib,mtk_fx_envhi,mtk_fx_envlo,mtk_fx_envsh
        dw mtk_fx_noise,mtk_fx_none,mtk_fx_cont,mtk_fx_jump,mtk_fx_cut,mtk_fx_break,mtk_fx_detune,mtk_fx_speed

mtk_fx_arp: ld a,c
        or a
        jr nz,mtk_fxa_on
        ld (ix+mtk_C_FX),0FFh       ; 000 stops the running effect
        ret
mtk_fxa_on: ld (ix+mtk_C_FX),0
        ld (ix+mtk_C_FXP),c
        ret
mtk_fx_cont:                        ; 1xx, 2xx, Axy
        ld a,b
        and 0Fh
        ld (ix+mtk_C_FX),a
        ld (ix+mtk_C_FXP),c
        ret
mtk_fx_porta:
        ld (ix+mtk_C_FX),3
        ld a,c
        or a
        ret z
        ld (ix+mtk_C_PSPD),a
        ret
mtk_fx_vib: ld (ix+mtk_C_FX),4
        ld a,c
        or a
        ret z
        ld (ix+mtk_C_VIBPAR),a
        ret
mtk_fx_envhi:
        ld a,c
        ld (mtk_PSGREG+12),a
        jr mtk_fx_envset
mtk_fx_envlo:
        ld a,c
        ld (mtk_PSGREG+11),a
mtk_fx_envset:
        ld a,1
        ld (mtk_PL_ENVMAN),a
        ret
mtk_fx_envsh:
        ld a,c
        and 0Fh
        ld (mtk_PSGREG+13),a
        ld a,1
        ld (mtk_PL_ENVTRIG),a
        ret
mtk_fx_noise:
        ld a,c
        cp 20h
        jr c,mtk_fxn_ok
        ld a,0FFh
mtk_fxn_ok: ld (ix+mtk_C_NOVR),a
mtk_fx_none:
        ret
mtk_fx_jump:
        ld a,c
        ld (mtk_PL_JUMP),a
        ret
mtk_fx_cut: ld (ix+mtk_C_CUT),c
        ret
mtk_fx_break:
        ld a,c
        ld (mtk_PL_BREAK),a
        ret
mtk_fx_detune:
        ld (ix+mtk_C_DET),c
        ret
mtk_fx_speed:
        ld a,c
        or a
        ret z
        ld (mtk_PL_SPEED),a
        ret

; ---------------------------------------------------------------------------
; Per-frame channel update: instrument sequence + running effects -> outputs
; ---------------------------------------------------------------------------
mtk_chan_tick:
        ld a,(ix+mtk_C_DLY)
        or a
        jr z,mtk_ct_nodly
        dec a
        ld (ix+mtk_C_DLY),a
        jr nz,mtk_ct_nodly
        ld d,(ix+mtk_C_DNOTE)
        ld e,(ix+mtk_C_DIV)
